<script setup lang="ts">
import { usePage } from '@inertiajs/vue3';
import { computed, onBeforeUnmount, ref, watch } from 'vue';
interface ProductCardData { id:number; name:string; mpn:string; cost:number; stock_qty:number; images?:{image:string}[]; total_unique_views?:number; scent_families?:string|null; seo?:{slug:string} }
const props=defineProps<{product:ProductCardData;className?:string;wishlisted?:boolean}>();
const emit=defineEmits(['addToCart','favourite']);
const page=usePage();
const isWishlisted=ref(props.wishlisted??false);
const cartState=ref<'idle'|'adding'|'added'>('idle');
const quantity=ref(1);
let cartTimer:ReturnType<typeof setTimeout>|undefined;
watch(()=>props.wishlisted,(value)=>{isWishlisted.value=value??false});
const isPopular=computed(()=>(props.product.total_unique_views||0)>100);
const isInCart=computed(()=>((page.props as {cartProductIds?:number[]}).cartProductIds??[]).includes(props.product.id));
const isLowStock=computed(()=>props.product.stock_qty>0&&props.product.stock_qty<=5);
const imageUrl=computed(()=>props.product.images?.[0]?.image);
const scentLabel=computed(()=>{const values=props.product.scent_families?.split(',').map((value)=>value.trim().replaceAll('_',' ').replace(/\b\w/g,(letter)=>letter.toUpperCase())).filter(Boolean).slice(0,2);return values?.length?values.join(' · '):props.product.name.toLowerCase().includes('refill')?'Reed diffuser refill':'Handmade reed diffuser'});
const price=computed(()=>`£${Number(props.product.cost).toFixed(2)}`);
const productLink=computed(()=>props.product.seo?.slug?`/product/${props.product.seo.slug}`:`/product/${props.product.id}`);
function toggleFavourite(){isWishlisted.value=!isWishlisted.value;emit('favourite',props.product.id)}
function updateQuantity(value:number){quantity.value=Math.min(props.product.stock_qty,Math.max(1,Math.floor(value)||1))}
function addToCart(){if(cartState.value!=='idle'||props.product.stock_qty<=0)return;cartState.value='adding';emit('addToCart',quantity.value);cartTimer=setTimeout(()=>{cartState.value='added';cartTimer=setTimeout(()=>{cartState.value='idle'},1800)},550)}
onBeforeUnmount(()=>clearTimeout(cartTimer));
</script>

<template>
    <article class="product-card" :class="className">
        <div class="product-visual">
            <a :href="productLink" :aria-label="`View ${product.name}`"><img v-if="imageUrl" :src="imageUrl" :alt="product.name" loading="lazy" /><span v-else class="placeholder">Chapter of You</span></a>
            <span v-if="isLowStock" class="badge badge--stock">Only {{ product.stock_qty }} left</span><span v-else-if="isPopular" class="badge">Popular</span>
            <button type="button" class="wishlist" :class="{'wishlist--active':isWishlisted}" :aria-label="isWishlisted?`Remove ${product.name} from wishlist`:`Add ${product.name} to wishlist`" @click="toggleFavourite"><svg viewBox="0 0 24 24" :fill="isWishlisted?'currentColor':'none'" stroke="currentColor" stroke-width="2"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1 7.8 7.7 7.8-7.7 1-1.1a5.5 5.5 0 0 0 0-7.8Z" /></svg></button>
            <div v-if="product.stock_qty<=0" class="out-of-stock">Out of stock</div>
        </div>
        <div class="product-body">
            <p class="product-type">{{ scentLabel }}</p><a :href="productLink"><h3>{{ product.name }}</h3></a>
            <div class="product-price"><strong>{{ price }}</strong><span v-if="product.stock_qty>0">In stock</span></div>
            <div class="product-actions"><div class="quantity-control"><button type="button" :disabled="quantity<=1||cartState!=='idle'" :aria-label="`Decrease quantity of ${product.name}`" @click="updateQuantity(quantity-1)">−</button><input :value="quantity" type="number" min="1" :max="product.stock_qty" inputmode="numeric" :aria-label="`Quantity of ${product.name}`" :disabled="product.stock_qty<=0||cartState!=='idle'" @input="updateQuantity(Number(($event.target as HTMLInputElement).value))" /><button type="button" :disabled="quantity>=product.stock_qty||cartState!=='idle'" :aria-label="`Increase quantity of ${product.name}`" @click="updateQuantity(quantity+1)">+</button></div><button type="button" class="cart-button" :class="[`cart-button--${cartState}`,{'cart-button--in-cart':isInCart&&cartState==='idle'}]" :disabled="product.stock_qty<=0||cartState!=='idle'" @click="addToCart"><span v-if="cartState==='adding'" class="spinner" aria-hidden="true"></span><svg v-else-if="cartState==='added'||isInCart" aria-hidden="true" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6" /></svg><svg v-else aria-hidden="true" viewBox="0 0 24 24"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4ZM3 6h18M16 10a4 4 0 0 1-8 0" /></svg>{{ product.stock_qty<=0?'Unavailable':cartState==='adding'?'Adding':cartState==='added'?'Added':isInCart?'Add another':'Add to basket' }}</button></div>
        </div>
    </article>
</template>

<style scoped>
.product-card{height:100%;display:flex;flex-direction:column;color:var(--coy-color-text)}.product-visual{position:relative;aspect-ratio:1/1.08;overflow:hidden;background:var(--coy-color-champagne);border-radius:var(--coy-radius-md)}.product-visual>a{display:block;width:100%;height:100%}.product-visual img{width:100%;height:100%;display:block;object-fit:cover;transition:transform .45s var(--coy-ease)}.product-card:hover img{transform:scale(1.035)}.placeholder{width:100%;height:100%;display:grid;place-items:center;color:var(--coy-color-heading);font-family:var(--coy-font-display);font-size:1.35rem}.badge{position:absolute;top:.75rem;left:.75rem;padding:.45rem .7rem;color:white;background:var(--coy-color-accent);border-radius:999px;font-size:1rem;font-weight:700;line-height:1}.badge--stock{background:#805022}.wishlist{position:absolute;top:.65rem;right:.65rem;width:2.75rem;height:2.75rem;display:grid;place-items:center;color:var(--coy-color-accent);background:rgb(255 253 251/94%);border:1px solid var(--coy-color-border);border-radius:50%;cursor:pointer}.wishlist:hover,.wishlist--active{background:var(--coy-color-blush)}.wishlist svg{width:1.25rem}.wishlist--active svg{animation:favourite-pop .35s var(--coy-ease)}.out-of-stock{position:absolute;inset:auto 0 0;padding:.7rem;color:var(--coy-color-heading);background:rgb(250 246 242/94%);font-size:1rem;font-weight:700;text-align:center}.product-body{display:flex;flex:1;flex-direction:column;padding-top:1rem}.product-type{margin:0;color:var(--coy-color-accent);font-size:1rem;font-weight:600;line-height:1.4}.product-body>a{color:var(--coy-color-heading);text-decoration:none}.product-body h3{margin:.25rem 0 0;font-family:var(--coy-font-display);font-size:1.4rem;font-weight:600;line-height:1.2}.product-body h3:hover{color:var(--coy-color-accent)}.product-price{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin:.85rem 0;padding-top:.75rem;border-top:1px solid var(--coy-color-border-soft)}.product-price strong{color:var(--coy-color-heading);font-size:1.125rem}.product-price span{color:var(--coy-color-success);font-size:1rem;font-weight:600}.product-actions{display:grid;grid-template-columns:1fr auto;gap:.5rem;margin-top:auto}.product-actions>a,.product-actions button{min-height:2.75rem;display:inline-flex;align-items:center;justify-content:center;gap:.4rem;padding:.55rem 1rem;border-radius:999px;font-size:1rem;font-weight:700;text-decoration:none}.product-actions>a{color:var(--coy-color-heading);background:var(--coy-color-surface);border:1px solid var(--coy-color-border)}.product-actions>a:hover{border-color:var(--coy-color-rose-gold)}.product-actions button{min-width:6.75rem;color:white;background:var(--coy-color-accent);border:1px solid var(--coy-color-accent);font-family:inherit;cursor:pointer;transition:background .2s,color .2s,transform .2s}.product-actions button:hover:not(:disabled){background:var(--coy-color-accent-hover);transform:translateY(-1px)}.product-actions button:disabled{opacity:.7;cursor:not-allowed}.product-actions .cart-button--added{color:white;background:var(--coy-color-success);border-color:var(--coy-color-success);animation:added-pulse .35s var(--coy-ease)}.product-actions svg{width:1rem;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.spinner{width:1rem;height:1rem;border:2px solid rgb(255 255 255/45%);border-top-color:white;border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@keyframes added-pulse{50%{transform:scale(1.04)}}@keyframes favourite-pop{50%{transform:scale(1.25)}}
.product-actions{grid-template-columns:auto minmax(0,1fr)}.quantity-control{height:2.75rem;display:grid;grid-template-columns:2.35rem 2.4rem 2.35rem;overflow:hidden;background:var(--coy-color-surface);border:1px solid var(--coy-color-border);border-radius:999px}.product-actions .quantity-control button{min-width:0;min-height:0;padding:0;color:var(--coy-color-heading);background:transparent;border:0;border-radius:0}.product-actions .quantity-control button:hover:not(:disabled){color:var(--coy-color-accent);background:var(--coy-color-blush);transform:none}.quantity-control input{width:100%;padding:0;color:var(--coy-color-heading);background:transparent;border:0;border-right:1px solid var(--coy-color-border-soft);border-left:1px solid var(--coy-color-border-soft);font:700 1rem var(--coy-font-body);text-align:center;-moz-appearance:textfield}.quantity-control input::-webkit-inner-spin-button,.quantity-control input::-webkit-outer-spin-button{margin:0;-webkit-appearance:none}.cart-button{width:100%}
.product-actions .cart-button--in-cart{background:var(--coy-color-heading);border-color:var(--coy-color-heading)}
@media(max-width:600px){.product-visual{aspect-ratio:1/1}.product-body h3{font-size:1.25rem}.product-price span{display:none}.product-actions{grid-template-columns:auto minmax(0,1fr)}}
@media(prefers-reduced-motion:reduce){.product-visual img,.product-actions button{transition:none}.wishlist--active svg,.product-actions .cart-button--added,.spinner{animation:none}}
</style>
